package internal

import "sync"

type account struct {
	user string
	pass string
}

var accounts = struct {
	sync.RWMutex
	items map[string]account
}{items: make(map[string]account)}

// RegisterAccount registers credentials for an etcd cluster.
func RegisterAccount(endpoints []string, user, pass string) {
	key := getClusterKey(endpoints)
	accounts.Lock()
	accounts.items[key] = account{user: user, pass: pass}
	accounts.Unlock()
}

func getAccount(endpoints []string) (account, bool) {
	key := getClusterKey(endpoints)
	accounts.RLock()
	item, ok := accounts.items[key]
	accounts.RUnlock()
	return item, ok
}
